<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\{Event,EventPerformance,Media,Teacher};use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;
class EventPerformanceController extends Controller{
 public function index(Event $event){return view('admin.events.performances',['event'=>$event,'items'=>$event->performances()->with(['teacher','media'])->get(),'teachers'=>Teacher::where('is_active',true)->orderBy('name')->get()]);}
 public function store(Request $r,Event $event){$d=$this->data($r);$d['event_id']=$event->id;$p=EventPerformance::create($d);$this->media($r,$p);return back()->with('ok','Выступление добавлено');}
 public function update(Request $r,Event $event,EventPerformance $performance){abort_unless($performance->event_id===$event->id,404);$performance->update($this->data($r));$this->remove($r,$performance);$this->media($r,$performance);return back()->with('ok','Выступление обновлено');}
 public function destroy(Event $event,EventPerformance $performance){abort_unless($performance->event_id===$event->id,404);foreach($performance->media as $m){if($m->file)Storage::disk('public')->delete($m->file);$m->delete();}$performance->delete();return back()->with('ok','Выступление удалено');}
 private function data(Request $r){$d=$r->validate(['program_number'=>'required|integer|min:1','student_name'=>'required|max:255','student_class'=>'nullable|max:100','title'=>'required|max:255','composer'=>'nullable|max:255','instrument'=>'nullable|max:255','teacher_id'=>'nullable|exists:teachers,id','accompanist'=>'nullable|max:255','description'=>'nullable']);$d['is_published']=$r->boolean('is_published');return $d;}
 private function media(Request $r,EventPerformance $p):void{$r->validate(['photos'=>'nullable|array|max:30','photos.*'=>'image|max:15360','panoramas'=>'nullable|array|max:10','panoramas.*'=>'image|max:30720','audio'=>'nullable|file|max:51200|mimes:mp3,wav,ogg,m4a,aac','video_url'=>'nullable|url|max:1000']);$sort=(int)($p->media()->max('event_performance_media.sort')??0)+1;
 foreach($r->file('photos',[]) as $f){$path=$f->store('performances/photos','public');$m=Media::create(['name'=>$f->getClientOriginalName(),'file'=>$path,'media_type'=>'file','mime'=>$f->getMimeType(),'size'=>$f->getSize(),'collection'=>'performance']);$p->media()->attach($m->id,['sort'=>$sort++]);}
 foreach($r->file('panoramas',[]) as $f){$path=$f->store('performances/panoramas','public');$m=Media::create(['name'=>$f->getClientOriginalName(),'file'=>$path,'media_type'=>'panorama','mime'=>$f->getMimeType(),'size'=>$f->getSize(),'collection'=>'performance']);$p->media()->attach($m->id,['sort'=>$sort++]);}
 if($r->hasFile('audio')){$f=$r->file('audio');$path=$f->store('performances/audio','public');$m=Media::create(['name'=>$f->getClientOriginalName(),'file'=>$path,'media_type'=>'audio','mime'=>$f->getMimeType(),'size'=>$f->getSize(),'collection'=>'performance']);$p->media()->attach($m->id,['sort'=>$sort++]);}
 if($r->filled('video_url')){$url=$r->video_url;$provider=str_contains($url,'youtu.be')||str_contains($url,'youtube.com')?'youtube':(str_contains($url,'rutube.ru')?'rutube':null);if(!$provider)throw \Illuminate\Validation\ValidationException::withMessages(['video_url'=>'Разрешены ссылки только YouTube и Rutube.']);$m=Media::create(['name'=>$p->student_name.' — '.$p->title,'file'=>'','external_url'=>$url,'provider'=>$provider,'media_type'=>'video','mime'=>'video/external','size'=>0,'collection'=>'performance']);$p->media()->attach($m->id,['sort'=>$sort]);}}
 private function remove(Request $r,EventPerformance $p):void{foreach((array)$r->input('remove_media',[]) as $id){$m=$p->media()->where('media.id',$id)->first();if(!$m)continue;$p->media()->detach($m->id);if($m->file)Storage::disk('public')->delete($m->file);$m->delete();}}
}